        //     0000XXXX - Bank + $0000
        //     0001XXXX - Bank + $0400
        //     0010XXXX - Bank + $0800
        //     0011XXXX - Bank + $0c00
        //     0100XXXX - Bank + $1000
        //     0101XXXX - Bank + $1400
        //     0110XXXX - Bank + $1800
        //     0111XXXX - Bank + $1c00
        //     1000XXXX - Bank + $2000
        //     1001XXXX - Bank + $2400
        //     1010XXXX - Bank + $2800
        //     1011XXXX - Bank + $2c00
        //     1100XXXX - Bank + $3000
        //     1101XXXX - Bank + $3400
        //     1110XXXX - Bank + $3800
        //     1111XXXX - Bank + $3c00
        //
        // CharSet Location ($d018), LSB used for lower/Upper character set:
        //     XXXX000X - Bank + $0000
        //     XXXX001X - Bank + $0800
        //     XXXX010X - Bank + $1000
        //     XXXX011X - Bank + $1800
        //     XXXX100X - Bank + $2000
        //     XXXX101X - Bank + $2800
        //     XXXX110X - Bank + $3000
        //     XXXX111X - Bank + $3800
        //
        // Bitmap Location ($d018):
        //     XXXX0XXX - Bank + $0000
        //     XXXX1XXX - Bank + $2000
        :lda #[[[SCRMem.getValue() & %0011110000000000] >> 6] | [[BMPMem.getValue() & %0011110000000000]>> 10]]
